import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  Img,
  interpolate,
  spring,
  random,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type PulsatingBorderProps = Record<string, any>;

const PulsatingBorder: React.FC<PulsatingBorderProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  imageUrl = "https://images.unsplash.com/photo-1550684848-fac1c5b4e853?q=80&w=1000&auto=format&fit=crop",
  primaryColor = "#8A2BE2", // Updated: Vivid Blue-Violet
  secondaryColor = "#00FFC2", // Updated: Neon Teal/Cyan
  glowIntensity = 40,
  pulseSpeed = 1.5,
  borderRadius = 20,
  particleCount = 30,
  imageScale = 0.6,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  const contentSize = Math.min(width, height) * imageScale;

  // Entrance animation
  const entrance = spring({
    frame,
    fps,
    config: { damping: 12 },
  });

  // Futuristic Pulse Logic (Sharper, more electronic)
  const pulseLoop = (frame / fps) * pulseSpeed * Math.PI;
  // Use a power curve to make the pulse 'spike' rather than sine wave breathe
  const normalizedPulse = (Math.sin(pulseLoop) + 1) / 2; // 0 to 1
  const techPulse = Math.pow(normalizedPulse, 4); // Stays low longer, peaks sharply
  
  const pulseScale = interpolate(techPulse, [0, 1], [1, 1.05]);
  const pulseOpacity = interpolate(techPulse, [0, 1], [0.5, 1]);

  // Scanline Animation
  const scanDuration = 3 * fps;
  const scanProgress = (frame % scanDuration) / scanDuration;
  const scanTop = interpolate(scanProgress, [0, 1], [-20, 120]);

  // Gradient Rotation
  const rotation = interpolate(
    frame,
    [0, durationInSeconds * fps],
    [0, 360]
  );

  // Generate deterministic particles (Digital bits)
  const particles = useMemo(() => {
    return new Array(particleCount).fill(0).map((_, i) => {
      const seed = i * 1337;
      const side = Math.floor(random(seed) * 4); // 0: top, 1: right, 2: bottom, 3: left
      const offset = random(seed + 1); // Position along the side (0-1)
      const speed = 0.5 + random(seed + 2) * 1.5;
      const size = 2 + random(seed + 3) * 6;
      const lifeOffset = random(seed + 4) * fps * 2;
      return { side, offset, speed, size, lifeOffset };
    });
  }, [particleCount, fps]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <AbsoluteFill
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${entrance})`,
        }}
      >
        {/* Glow Layer - Updated to conic gradient to flow AROUND the image */}
        <div
          style={{
            position: "absolute",
            width: contentSize,
            height: contentSize,
            borderRadius: borderRadius,
            background: `conic-gradient(from ${rotation}deg, ${primaryColor}, ${secondaryColor}, ${primaryColor})`,
            filter: `blur(${glowIntensity}px)`,
            opacity: pulseOpacity * 0.8,
            transform: `scale(${pulseScale})`,
            transition: "none",
          }}
        />

        {/* Rotating Border Layer - Fluid gradient flow */}
        <div
          style={{
            position: "absolute",
            width: contentSize + 10,
            height: contentSize + 10,
            borderRadius: borderRadius + 2,
            background: `conic-gradient(from ${rotation}deg, ${primaryColor}, ${secondaryColor}, ${primaryColor})`,
            opacity: 1,
            transition: "none",
            boxShadow: `0 0 ${glowIntensity / 3}px ${primaryColor}40`,
            // Create a mask to make the gradient border thin
            mask: `linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)`,
            maskComposite: "exclude",
            padding: "3px", // Border thickness
            clipPath: `inset(0px round ${borderRadius + 2}px)`, // Ensure sharp clipping
          }}
        />

        {/* Solid background for the conic gradient to sit on, ensuring visibility */}
        <div 
           style={{
            position: "absolute",
            width: contentSize + 10,
            height: contentSize + 10,
            borderRadius: borderRadius + 2,
            background: `conic-gradient(from ${rotation}deg, ${primaryColor}, ${secondaryColor}, ${primaryColor})`,
            opacity: 0.6,
            zIndex: -1,
           }}
        />

        {/* Tech Wireframe Ring (Static Rotation, Scaling Pulse) */}
        <div
          style={{
            position: "absolute",
            width: contentSize + 25,
            height: contentSize + 25,
            borderRadius: borderRadius + 8,
            border: `1px solid ${primaryColor}40`,
            opacity: pulseOpacity,
            transform: `scale(${pulseScale})`,
            transition: "none",
          }}
        />

        {/* Particle System (Digital Bits) */}
        <div
          style={{
            position: "absolute",
            width: contentSize + 60,
            height: contentSize + 60,
            pointerEvents: "none",
          }}
        >
          {particles.map((p, i) => {
            // Calculate position
            const progress = (frame + p.lifeOffset) % (fps * 4);
            const normalizedProgress = progress / (fps * 4);
            
            // Fade in/out cycle
            const alpha = interpolate(
              normalizedProgress, 
              [0, 0.2, 0.8, 1], 
              [0, 1, 1, 0]
            );

            // Movement
            const move = interpolate(
              normalizedProgress,
              [0, 1],
              [0, 60 * p.speed]
            );

            let top = "0%";
            let left = "0%";
            let transform = "";

            // Position logic based on side
            if (p.side === 0) { // Top
              top = "0%";
              left = `${p.offset * 100}%`;
              transform = `translateY(-${move}px)`;
            } else if (p.side === 1) { // Right
              top = `${p.offset * 100}%`;
              left = "100%";
              transform = `translateX(${move}px)`;
            } else if (p.side === 2) { // Bottom
              top = "100%";
              left = `${p.offset * 100}%`;
              transform = `translateY(${move}px)`;
            } else { // Left
              top = `${p.offset * 100}%`;
              left = "0%";
              transform = `translateX(-${move}px)`;
            }

            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  top,
                  left,
                  width: p.size,
                  height: p.size,
                  backgroundColor: i % 2 === 0 ? primaryColor : secondaryColor,
                  borderRadius: "1px", // Square pixels for tech look
                  opacity: alpha,
                  transform: transform,
                  boxShadow: `0 0 ${p.size}px ${i % 2 === 0 ? primaryColor : secondaryColor}`,
                  transition: "none",
                }}
              />
            );
          })}
        </div>

        {/* Main Image Container */}
        <div
          style={{
            width: contentSize,
            height: contentSize,
            borderRadius: borderRadius,
            overflow: "hidden",
            position: "relative",
            zIndex: 10,
            backgroundColor: "#000",
            boxShadow: `inset 0 0 20px ${primaryColor}40`, // Inner glow
          }}
        >
          <Img
            src={imageUrl}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
            }}
          />
          
          {/* Futuristic Scanline */}
          <div 
             style={{
                position: "absolute",
                top: `${scanTop}%`,
                left: 0,
                right: 0,
                height: "15%",
                background: `linear-gradient(to bottom, transparent 0%, ${primaryColor}80 50%, transparent 100%)`,
                opacity: 0.6,
                mixBlendMode: "screen",
                pointerEvents: "none",
             }}
          />
          
          {/* Subtle Grid Overlay */}
          <div 
             style={{
                position: "absolute",
                inset: 0,
                backgroundImage: `linear-gradient(${primaryColor}20 1px, transparent 1px), linear-gradient(90deg, ${primaryColor}20 1px, transparent 1px)`,
                backgroundSize: "20px 20px",
                opacity: 0.2,
                pointerEvents: "none",
             }}
          />

          {/* Internal Shine/Gloss */}
          <div 
            style={{
                position: "absolute",
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                background: `linear-gradient(135deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0) 50%, rgba(255,255,255,0) 100%)`,
                pointerEvents: "none"
            }}
          />
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default PulsatingBorder;